import{z as m,x as o,o as e,c as u,q as l,j as i,D as t,d as n,s as B,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Feynman–Kac","description":"","frontmatter":{"title":"Feynman–Kac","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/feynman-kac.md","filePath":"quant/feynman-kac.md","lastUpdated":1791063341000}'),c={name:"quant/feynman-kac.md"};function h(A,a,d,p,_,f){const E=o("Mermaid");return e(),u("div",null,[a[2]||(a[2]=l('<h1 id="feynman–kac" tabindex="-1">Feynman–Kac <a class="header-anchor" href="#feynman–kac" aria-label="Permalink to &quot;Feynman–Kac&quot;">​</a></h1><div class="epigraph"><p>扩散的贴现期望满足柯尔莫哥洛夫后向方程：生成元作用在价格函数上，等于贴现与时间导数的平衡。</p><footer>—— 据 Karatzas and Shreve, 1991, §5.7；Øksendal, Stochastic Differential Equations, 第 6 版, 第 8 章；Shreve, Stochastic Calculus for Finance II, 第 6 章整理</footer></div><p>上一课<a href="/quant/incomplete-market">不全市场</a>说明多个 \\(Q\\) 时期望不唯一。本课回到已经选定一个测度、标的为扩散的情形。缺口是：\\(\\mathbb E[e^{-\\int r}g(X_T)\\mid X_t=x]\\) 如何变成关于 \\((t,x)\\) 的 PDE。没有这条桥，下一课无法把 Black–Scholes 写成方程。本课只给 Feynman–Kac 接口，不把 BSM 的边界条件写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>风险中性价格已经是条件期望。要计算它，一条路是模拟路径，另一条是解 PDE。缺口是承认两者是同一对象的两种写法：若 \\(u(t,x)\\) 足够光滑、满足终值 \\(u(T,x)=g(x)\\) 以及</p> \\[u_t+\\mathcal A u-r u=0, \\]<p>其中 \\(\\mathcal A\\) 是扩散在该测度下的生成元，则 \\(u(t,X_t)\\) 贴现后为鞅，从而 \\(u\\) 等于条件期望。反过来，在正则性下条件期望解这个 Cauchy 问题。</p><p>本课不重推 Itô。生成元 \\(\\mathcal A=\\mu\\partial_x+\\tfrac12\\sigma^2\\partial_{xx}\\) 已在伊藤引理里出现，这里只把它接到带杀灭（贴现）的期望。</p><h3 id="feynman–kac-不是量子力学的必经路" tabindex="-1">Feynman–Kac 不是量子力学的必经路 <a class="header-anchor" href="#feynman–kac-不是量子力学的必经路" aria-label="Permalink to &quot;Feynman–Kac 不是量子力学的必经路&quot;">​</a></h3><p>名字来自 Feynman 路径积分与 Kac 对 Schrödinger 半群的概率表示。金融只用概率这一侧：期望 \\(\\leftrightarrow\\) PDE。不必引入 Planck 常数或路径积分测度。把本课读成物理课，会把 \\(r\\) 当成势能乱配。</p><p><span class="marginnote">贴现 \\(r\\) 是零阶项。区域上的击中（障碍）把终时换成停时，PDE 换成边值；那是同一条公式的 Dirichlet 版，本课先钉全空间 Cauchy。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 \\(\\mathrm d X=\\mu(t,X)\\,\\mathrm d t+\\sigma(t,X)\\,\\mathrm d W\\)，取</p> \\[u(t,x)=\\mathbb E\\bigl[e^{-\\int_t^T r(s,X_s)\\mathrm d s}g(X_T)\\bigm|X_t=x\\bigr]. \\]<p>则（在多项式增长等条件下）\\(u\\) 解 \\(u_t+\\mu u_x+\\tfrac12\\sigma^2 u_{xx}-r u=0\\)，\\(u(T,\\cdot)=g\\)。若还有支付流 \\(f\\)，右端加 \\(-f\\)。多维把 \\(\\mathcal A\\) 写成梯度与 Hessian 的收缩。这是后课 BSM 的模板：把 \\(\\mu\\) 换成 \\(rS\\)、\\(\\sigma\\) 换成 \\(\\sigma S\\)、\\(g=(x-K)^+\\)。</p><p>反过来：用 Itô 作用 \\(e^{-\\int r}u(t,X_t)\\)，PDE 恰好取消漂移，剩下随机积分；取期望得表示。这是「验证定理」方向，数值上常先猜 PDE 再承认它是价格。</p><p><span class="marginnote">拿数字感受贴现项：设 \\(r=5\\%\\)、\\(u=100\\)，则 \\(ru\\) 这一项就是每年 5。PDE 要求 \\(u_t+\\mathcal A u\\) 恰好补上这 5——价格随时间的「损耗」由漂移与波动收益填补，贴现才不白算。</span></p>',17)),(e(),i(s,null,{default:t(()=>[B(E,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20EXP%5B%22Q%20%E4%B8%8B%E8%B4%B4%E7%8E%B0%E6%9C%9F%E6%9C%9B%22%5D%20--%3E%20FK%5B%22Feynman-Kac%22%5D%0A%20%20PDE%5B%22%E6%9F%AF%E5%B0%94%E8%8E%AB%E5%93%A5%E6%B4%9B%E5%A4%AB%E5%90%8E%E5%90%91%E6%96%B9%E7%A8%8B%22%5D%20--%3E%20FK%0A%20%20FK%20--%3E%20BSM%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9ABSM%20%E4%BD%9C%E4%B8%BA%20PDE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[n("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"Itô 把 \\(u(t,X_t)\\) 的漂移写成 \\(u_t+\\mathcal A u\\)。贴现的乘积法则再减 \\(r u\\)。令漂移为零，贴现价格成为局部鞅；可积时取条件期望，初值等于终端支付的贴现均值。PDE 因此不是另起的「期权方程」，而是鞅条件的微分形式。生成元用哪个 \\(\\mu\\)，就对应哪个测度：物理测度下是预测方程，风险中性下是定价方程。同一 \\(g\\)，不同 \\(\\mathcal A\\)，解不同——这与「\\(\\mu\\) 不进 BSM」一致：BSM 用的是 \\(Q\\) 的 \\(\\mathcal A\\)。",-1)),(e(),i(s,null,{default:t(()=>[B(E,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AF%B9%E8%B4%B4%E7%8E%B0%E9%87%8F%20e%5E(-%E2%88%ABr)%C2%B7u(t%2CX_t)%20%E7%94%A8%20It%C3%B4%22%5D%20--%3E%20B%5B%22%E5%BE%97%E5%88%B0%E6%BC%82%E7%A7%BB%E9%A1%B9%20u_t%20%2B%20Au%20-%20ru%22%5D%0A%20%20B%20--%3E%20C%5B%22PDE%20%E6%81%B0%E5%A5%BD%E4%BB%A4%E6%BC%82%E7%A7%BB%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%8F%AA%E5%89%A9%E9%9A%8F%E6%9C%BA%E7%A7%AF%E5%88%86%EF%BC%9A%E9%9E%85%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%8F%96%E6%9C%9F%E6%9C%9B%EF%BC%9A%E9%9A%8F%E6%9C%BA%E9%A1%B9%E5%9D%87%E5%80%BC%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20E%20--%3E%20F%5B%22u(t%2Cx)%20%3D%20%E8%B4%B4%E7%8E%B0%E7%BB%88%E7%AB%AF%E6%94%AF%E4%BB%98%E7%9A%84%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">生成元 \\(\\mathcal A\\) 可以翻译成「沿随机路径走一小步，函数 \\(u\\) 的平均变化率」的机器：喂入 \\(u\\)，它吐出漂移贡献 \\(\\mu u_x\\) 加上波动贡献 \\(\\tfrac12\\sigma^2 u_{xx}\\)。后一半来自 Itô 修正项，是初学者最容易漏掉的部分。</span></p><p><span class="marginnote">常见误区：以为 PDE 的解天生唯一。实际上齐次方程还允许许多增长极快的「多余解」；只有加上增长条件把它们排除，剩下的那个才等于条件期望。</span></p><p>边界与增长条件挡住爆炸解。没有它们，PDE 可能有许多解，只有多项式增长的那个等于期望。后课数值解要尊重这条，不能随便加一个快速增长的齐次解。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证一般半群理论，不处理积分-微分方程（跳）。美式把等式换成变分不等式，留给最优停课。后课默认：扩散 + 选定测度 \\(\\Rightarrow\\) 价格满足后向 Kolmogorov 加贴现。下一课<a href="/quant/bsm-as-pde">Black–Scholes 作为 PDE</a>把 \\(\\mathcal A\\) 特化成 GBM 在 \\(Q\\) 下的算子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贴现期望与带生成元的 PDE 是同一价格的两种写法。</li><li>\\(\\mathcal A\\) 取自用来取期望的那个测度。</li><li>验证方向：PDE 使贴现 \\(u(t,X_t)\\) 为鞅。</li><li>增长条件选出等于期望的那个解。</li><li>出处：Karatzas–Shreve §5.7；Øksendal 第 8 章；Shreve SDE II 第 6 章。</li></ul>',7))])}const x=m(c,[["render",h]]);export{F as __pageData,x as default};
